const icons={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',workflow:'M5 3h14v5H5z M5 16h14v5H5z M12 8v8',models:'M8 3h8l5 9-5 9H8l-5-9z M8 12h8',tools:'M14 4a6 6 0 0 0-7 7L3 18l3 3 7-5a6 6 0 0 0 7-7l-4 4-5-5z',storage:'M4 5c0-4 16-4 16 0v14c0 4-16 4-16 0z M4 5c0 4 16 4 16 0 M4 12c0 4 16 4 16 0',evaluations:'M5 3h14v18H5z M8 8l2 2 5-5 M8 15h8',policies:'M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6z M8 11l3 3 5-6',observability:'M2 12h4l3-8 5 16 3-8h5',security:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',cost:'M4 20V10 M10 20V4 M16 20v-8 M22 20H2',errors:'M12 3l10 18H2z M12 9v5 M12 17v1'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.workflow}"/></svg>`;
const modules=[['workflow','Workflow'],['models','Models'],['tools','Tools'],['storage','Storage & compute'],['evaluations','Evaluations'],['policies','Policies & approvals'],['observability','Observability & evidence'],['security','Security & guardrails'],['cost','Cost & latency'],['errors','Errors & incidents']];
let page='overview',scenario='approval',selected=3,mode='execution',approved=false,rejected=false,suiteRun=false,policyOpen=false,tab='metrics';
const steps=['Read customer','AI proposal','Evaluate proposal','Policy check','Execute refund','Verify outcome'];
const scenarios={success:{id:'RUN-1041',title:'Normal success',amount:4500},approval:{id:'RUN-1042',title:'Approval required',amount:15000},blocked:{id:'RUN-1043',title:'Customer mismatch',amount:4500},failure:{id:'RUN-1044',title:'Injected tool failure',amount:4500}};
function state(i){if(mode==='definition')return'Configured';if(scenario==='blocked'&&i>=3)return i===3?'Blocked':'Not reached';if(scenario==='approval'&&!approved&&i>=3)return i===3?(rejected?'Rejected':'Waiting approval'):'Not reached';if(scenario==='failure'&&i>=4)return i===4?'Failed':'Not reached';return'Passed'}
function pill(s){return `<span class="pill ${/Waiting|Blocked|Rejected|review|Pending/.test(s)?'amber':/Failed|Error/.test(s)?'red':/Unknown|Not reached|Configured|Unconnected/.test(s)?'gray':''}">${s}</span>`}
function metric(label,value,foot){return `<div class="metric"><div class="metric-label">${label}<span>↗</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`}
function go(p){page=p;render();window.scrollTo(0,0)}
function toast(t){const e=document.getElementById('toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),3000)}
function render(){document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">⌁</span>R2M<span style="font-size:9px;letter-spacing:0;color:#7ca08e;margin-left:auto">BETA</span></div><div class="tagline">RESPONSIBILITY TO MONITORING</div><div class="org"><span class="avatar">P</span><div style="font-size:11px">Personal workspace<small style="display:block;color:#8ea99c;margin-top:4px;font-size:9px">Hackathon prototype</small></div></div><div class="navlabel">ORGANIZATION</div><nav class="nav"><button data-page="overview" class="${page==='overview'?'active':''}" title="Overview">${icon('overview')}<span>Overview</span></button></nav><div class="navlabel">AGENT WORKSPACE</div><nav class="nav">${modules.map(([id,name])=>`<button data-page="${id}" title="${name}" class="${page===id?'active':''}">${icon(id)}<span>${name}</span>${id==='policies'&&!approved&&!rejected?'<b class="badge">1</b>':''}</button>`).join('')}</nav><div class="sidebottom"><span class="dot"></span>Local design preview<p>One agent. Every decision.<br>A connected evidence trail.</p><div class="person"><span class="avatar">MD</span><div>My workspace<small style="display:block;margin-top:4px;color:#688875">Personal · Demo identity</small></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Personal workspace <span>/</span> <strong>${page==='overview'?'Overview':'Support Operations Agent'}</strong></div><div class="topright"><span class="fresh" style="color:#8b978d">○ &nbsp; Synthetic dataset</span><span class="demo">INTERACTIVE PROTOTYPE</span></div></header><div class="content">${page==='overview'?overview():workspacePage()}</div></main></div>`;bind()}
function overview(){return `<div class="heading"><div><div class="eyebrow">Your AI operations, in one place</div><h1>Organization overview</h1><div class="subtitle">Understand what your agents do. Know who is responsible.</div></div><div class="controls"><span class="pill gray">Demo environment</span><span class="pill gray">Last hour · fixed sample</span><button class="primary" data-page="workflow">Open agent workspace ↗</button></div></div><div class="metrics">${metric('Run volume','24','Illustrative cohort · 23 terminal')}${metric('Verified completion','87.0%','20 verified / 23 terminal')}${metric('Technical failures','4.3%','1 failed / 23 terminal')}${metric('P95 run latency','2.8s','23 terminal runs · includes waits')}${metric('Model cost estimate','$0.18','Call-time window · 100% coverage')}${metric('Pending approvals',approved||rejected?'0':'1',approved||rejected?'Demo action resolved':'Oldest request · 2 min')}</div><div class="grid2"><section class="panel"><div class="panel-head"><h2>Run activity</h2><div class="legend"><span><i class="dot"></i>Completed</span><span style="color:#9da997">Last hour</span></div></div><div class="panel-body"><div style="display:flex;gap:10px;align-items:baseline"><span style="font-size:25px">24</span><span class="subtitle">runs across your organization</span></div><div class="chart" aria-label="Illustrative run activity distribution">${[25,35,20,50,38,65,45,35,75,55,40,88,65,80,55,95,70,85,60,75,90,70,55,80].map(x=>`<div class="bar" style="height:${x}%"></div>`).join('')}</div><div class="axis"><span>11:00</span><span>11:15</span><span>11:30</span><span>11:45</span><span>12:00</span></div></div></section><section class="panel"><div class="panel-head"><h2>Needs attention</h2><small>3 signals</small></div><div class="panel-body" style="padding-top:4px;padding-bottom:4px"><div class="attention"><span class="attention-icon">◷</span><div><strong>${approved||rejected?'Action review resolved':'A refund needs your approval'}</strong><p>Support Operations Agent · $150.00<br>REFUND-001 requires human review</p><button class="link" data-page="policies">Review request →</button></div></div><div class="attention"><span class="attention-icon" style="background:#faeeea;color:#ba7966">!</span><div><strong>Refund tool encountered an error</strong><p>Injected failure · RUN-1044</p><button class="link" data-scenario="failure">Inspect trace →</button></div></div><div class="attention"><span class="attention-icon" style="background:#eef3e9;color:#7b916a">◇</span><div><strong>Cloud telemetry isn't connected</strong><p>Compute billing and GPU metrics unavailable</p><button class="link" data-page="storage">View coverage →</button></div></div></div></section></div><section class="panel"><div class="panel-head"><div><h2>Agent registry <span class="pill gray" style="margin-left:8px">01</span></h2></div><span class="subtitle">One connected demo agent</span></div><div class="table-scroll"><table><thead><tr><th>AGENT / OWNER</th><th>STATUS</th><th>RUNS</th><th>VERIFIED COMPLETION</th><th>MODEL COST</th><th>REVIEWS</th><th></th></tr></thead><tbody><tr class="clickrow" data-page="workflow" tabindex="0" role="button" aria-label="Open Support Operations Agent"><td><div class="agent-name"><span class="agent-icon">⌘</span><div><strong>Support Operations Agent</strong><small>Personal team · Workflow v1.3</small></div></div></td><td>${pill('Healthy')}</td><td>24</td><td>87.0% <span style="color:#9ba594">/ 23</span></td><td>$0.18 <small style="color:#8a9787">estimated</small></td><td>${pill(approved||rejected?'Resolved':'1 Pending')}</td><td>↗</td></tr></tbody></table></div></section><div class="bottomnote"><span>◌ All values are illustrative. No live agent or cloud account is connected.</span><span>R2M / Control plane v0.1</span></div>`}
function workspacePage(){const title=modules.find(x=>x[0]===page)?.[1];return `<div class="heading"><div><div class="eyebrow">Agent workspace / ${title}</div><h1>${page==='workflow'?'Support Operations Agent':title}</h1><div class="subtitle">${page==='workflow'?'Follow every step, from intent to verified outcome.':'Support Operations Agent · Connected context across every layer.'}</div></div><div class="controls"><select id="scenario" aria-label="Select demo scenario">${Object.entries(scenarios).map(([id,s])=>`<option value="${id}" ${scenario===id?'selected':''}>${s.id} · ${s.title}</option>`).join('')}</select><button class="primary" id="replay">↻ Replay demo</button></div></div><div class="workspace-stats"><span>Environment<strong>Demo</strong></span><span>Workflow<strong>v1.3</strong></span><span>Trace<strong>${scenarios[scenario].id}</strong></span><span>Source<strong>Illustrative fixtures</strong></span></div>${page==='workflow'?workflow():page==='policies'?policies():page==='observability'?observability():page==='evaluations'?evaluations():page==='storage'?storage():page==='security'?security():page==='errors'?errors():layer()}<div class="bottomnote"><span>Frontend simulation only · Controls do not execute tools or change a real policy.</span><span>Personal workspace</span></div>`}
function node(i){const s=state(i);return `<button class="node ${selected===i?'selected':''}" data-node="${i}" data-state="${s}"><div class="node-top"><span style="color:#75977d">${['▤','✧','☑','◇','⌘','◎'][i]}</span>${steps[i]}</div><span class="node-status" style="color:${s==='Failed'?'#c97662':/Waiting|Blocked|Rejected/.test(s)?'#bc953f':s==='Not reached'?'#9aa59a':'#3c9970'}">${s==='Passed'?'✓':s==='Failed'?'!':s==='Not reached'?'○':'◌'}</span><small>${s} <span style="float:right">${s==='Passed'?['12 ms','820 ms','8 ms','3 ms','145 ms','9 ms'][i]:'—'}</span></small></button>`}
function workflow(){return `<div class="workspace"><section class="panel"><div class="graph-toolbar"><div class="segmented"><button data-mode="execution" class="${mode==='execution'?'selected':''}">Run execution</button><button data-mode="definition" class="${mode==='definition'?'selected':''}">Workflow definition</button></div><span class="pill gray">6 steps</span></div><div class="graph">${steps.map((_,i)=>`${i?'<div class="connector"></div>':''}${node(i)}`).join('')}</div><div class="graph-foot"><span>🟢 Passed</span><span>🔴 Failed</span><span>🟠 Review / blocked</span><span>○ Not reached</span></div></section><aside class="panel inspector">${inspector()}</aside></div><section class="panel sectiongap"><div class="panel-head"><h2>Execution events</h2><button class="link" data-page="observability">Open full trace →</button></div>${traceRows(3)}</section>`}
function inspector(){const s=state(selected);return `<div class="panel-head"><h2>Step inspector</h2><small>0${selected+1} / 06</small></div><div class="panel-body"><div class="eyebrow">${selected===3?'Runtime authorization':'Workflow operation'}</div><h3>${steps[selected]}</h3>${pill(s)}<div class="segmented" style="margin-top:22px"><button data-tab="metrics" class="${tab==='metrics'?'selected':''}">Details</button><button data-tab="payload" class="${tab==='payload'?'selected':''}">Input / output</button></div>${tab==='metrics'?`<div class="inspectlabel">Execution context</div><div class="kv"><span>Run ID</span><strong>${scenarios[scenario].id}</strong></div><div class="kv"><span>Attempt</span><strong>${s==='Not reached'?'0':'1'}</strong></div><div class="kv"><span>Enforcement</span><strong>Simulated</strong></div><div class="kv"><span>Policy version</span><strong>REFUND-001 / v1.2</strong></div><div class="inspectlabel">Decision</div><p class="subtitle">${selected===3?(scenario==='blocked'?'Customer identity does not match. The proposed action is denied.':scenario==='approval'?'Refunds above $100 require approval for this exact action.':'The proposed refund meets the automatic authorization rule.'):'This step belongs to the selected demonstration run. Inputs and results are synthetic.'}</p>`:`<div class="inspectlabel">Sanitized input</div><pre>${JSON.stringify({customer_id:scenario==='blocked'?'cus_other':'cus_demo_01',amount_cents:scenarios[scenario].amount,currency:'USD'},null,2)}</pre><div class="inspectlabel">Captured output</div><pre>${JSON.stringify({step:steps[selected],status:s,source:'demo_fixture'},null,2)}</pre>`}${scenario==='approval'&&!approved&&!rejected&&selected===3?`<div class="approvalbox"><strong>Human review required</strong><br>$150.00 · Customer demo_01<br>Approval applies only to this action.<div><button class="primary" id="approve">Approve demo</button> <button id="reject">Reject</button></div></div>`:''}<div class="inspectlabel">Evidence links</div><button class="link" data-page="policies">Applied policy ↗</button><br><button class="link" data-page="observability">View execution trace ↗</button></div>`}
function traceRows(count=6){return steps.slice(0,count).map((s,i)=>`<div class="trace-row"><time>00:0${i}.${i*12+10}</time><button class="link" data-node="${i}">${s}</button>${pill(state(i))}</div>`).join('')}
function observability(){return `<section class="panel"><div class="panel-head"><div><h2>Execution trace · ${scenarios[scenario].id}</h2><p class="subtitle">Input → decisions → action → verified outcome</p></div><button id="export">↓ Export demo evidence</button></div>${traceRows()}<div class="panel-body"><div class="eyebrow">Trace context</div><pre>${JSON.stringify({trace_id:scenarios[scenario].id,workflow:'v1.3',policy:'REFUND-001 v1.2',customer_policy:'IDENTITY-002 v1.0',source:'synthetic_frontend_fixture',signed:false},null,2)}</pre></div></section>`}
function policies(){return `<div class="grid2"><section class="panel"><div class="panel-head"><h2>Policy inventory</h2><span class="pill gray">2 policies</span></div><div class="table-scroll"><table><thead><tr><th>POLICY</th><th>VERSION</th><th>OWNER</th><th>STATUS</th></tr></thead><tbody><tr class="clickrow" id="policy-open" tabindex="0" role="button"><td><strong>Refund authorization</strong><div class="subtitle">REFUND-001</div></td><td>v1.2</td><td>Demo developer</td><td>${pill('Active')} ↗</td></tr><tr><td><strong>Customer identity boundary</strong><div class="subtitle">IDENTITY-002</div></td><td>v1.0</td><td>Demo developer</td><td>${pill('Active')}</td></tr></tbody></table></div>${policyOpen?`<div class="policy-detail"><div class="eyebrow">REFUND-001 / v1.2</div><h3>Refund authorization</h3><p>Eligible refunds up to $100 may proceed automatically. Above $100, require approval before the tool executes.</p><div class="kv"><span>Created by</span><strong>Demo developer</strong></div><div class="kv"><span>Approved by</span><strong>Demo reviewer</strong></div><div class="kv"><span>Enforcement location</span><strong>Before issueSyntheticRefund</strong></div><div class="kv"><span>Lifecycle</span><strong>Draft → Review → Approved → Active</strong></div><button class="link" data-page="evaluations">View policy tests →</button></div>`:'<div class="panel-body subtitle">Select Refund authorization to inspect ownership, rules, and enforcement.</div>'}</section><section class="panel"><div class="panel-head"><h2>Action approvals</h2>${pill(approved?'Approved':rejected?'Rejected':'Pending')}</div><div class="panel-body"><div class="eyebrow">RUN-1042 / Synthetic refund</div><h3 class="detail-title" style="margin-top:15px">Review $150.00 refund</h3><p class="subtitle">Customer demo_01 · Billing adjustment<br>This request exceeds the $100 automatic limit.</p><pre>{ "amount_cents": 15000,\n  "customer": "cus_demo_01",\n  "policy": "REFUND-001 v1.2" }</pre>${!approved&&!rejected?'<button class="primary" id="approve">Approve demo action</button> <button id="reject">Reject</button>':'<p class="subtitle">Decision recorded in this browser session. This is a simulation.</p>'}<p class="subtitle">Action approval is separate from policy publication review.</p></div></section></div>`}
function evaluations(){return `<section class="panel"><div class="panel-head"><div><h2>Evaluation suite</h2><p class="subtitle">Deterministic checks · Dataset demo-v1 · Workflow v1.3</p></div><button class="primary" id="suite">${suiteRun?'↻ Replay':'▷ Run'} demo suite</button></div><div class="table-scroll"><table><thead><tr><th>TEST CASE</th><th>EXPECTED ROUTE</th><th>RESULT</th></tr></thead><tbody>${[['Valid $45 refund','Execute and verify'],['Refund above $100','Wait for approval'],['Cross-customer request','Block action'],['Injected tool failure','Record technical failure'],['Evaluator timeout','Block execution']].map(([n,r])=>`<tr><td>${n}</td><td>${r}</td><td>${pill(suiteRun?'Passed':'Not run')}</td></tr>`).join('')}</tbody></table></div><div class="panel-body subtitle">${suiteRun?'5 / 5 illustrative expected-route matches. No actual tests were executed.':'Preview the expected evaluation results with the demo suite.'}<br>Hosted CI and real build checks are not connected.</div></section>`}
function storage(){return `<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric('Storage reads','2','Selected fixture · local record lookup')}${metric('Storage writes',state(4)==='Passed'?'1':'0','Synthetic refund ledger')}${metric('Compute cost','—','Billing source not connected')}</div><section class="panel"><div class="panel-head"><h2>Infrastructure coverage</h2>${pill('Unconnected')}</div><div class="empty"><div class="emptyicon">▱</div><h3>Connect infrastructure when you're ready</h3><p>This design reserves space for process CPU, memory, storage timings, and cloud billing. No live measurements are available in this frontend.</p><span class="pill gray">Local process · Not instrumented</span> <span class="pill gray">Cloud account · Not connected</span></div></section>`}
function security(){return `<section class="panel"><div class="panel-head"><h2>Policy → guardrail → evidence</h2><small>Demo bindings</small></div><div class="table-scroll"><table><thead><tr><th>GUARDRAIL</th><th>POLICY VERSION</th><th>ENFORCEMENT POINT</th><th>COVERAGE</th><th></th></tr></thead><tbody><tr><td>Refund approval threshold</td><td>REFUND-001 v1.2</td><td>Tool boundary</td><td>${pill('Simulated')}</td><td><button class="link" data-page="policies">Inspect →</button></td></tr><tr><td>Customer identity validation</td><td>IDENTITY-002 v1.0</td><td>Before mutation</td><td>${pill('Simulated')}</td><td><button class="link" data-scenario="blocked">See blocked run →</button></td></tr><tr><td>Prompt injection detection</td><td>—</td><td>Not configured</td><td>${pill('Unknown')}</td><td>—</td></tr></tbody></table></div><div class="panel-body subtitle">A policy denial can be correct enforcement. It is not automatically a technical incident.</div></section>`}
function errors(){return `<section class="panel"><div class="panel-head"><h2>Error groups</h2><span class="pill red">1 fixture</span></div><div class="table-scroll"><table><thead><tr><th>ERROR</th><th>TOOL</th><th>OCCURRENCES</th><th>RUN</th><th></th></tr></thead><tbody><tr><td><strong>InjectedServiceUnavailable</strong><div class="subtitle">Deliberately simulated for the prototype</div></td><td>issueSyntheticRefund</td><td>1</td><td>RUN-1044</td><td><button class="link" data-scenario="failure">Inspect failure →</button></td></tr></tbody></table></div></section>`}
function layer(){if(page==='cost')return `<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric('Model estimate','$0.007','Illustrative usage × configured rate')}${metric('Compute / storage','—','No billing or allocation source')}${metric('Approval wait',scenario==='approval'?'2m 00s':'0s','Illustrative · separate from execution')}</div><section class="panel"><div class="panel-head"><h2>Usage attribution</h2><button class="link" data-page="observability">Open source trace →</button></div><div class="panel-body"><div class="kv"><span>Model attempt 1 · ${scenarios[scenario].id}</span><strong>$0.007 · estimated</strong></div><div class="progress"><span style="width:100%"></span></div><p class="subtitle">Model-only estimate. This is not total infrastructure cost. Pricing and tokens shown here are fixture values.</p></div></section>`;const model=page==='models';return `<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric(model?'Model calls':'Tool attempts',model?'1':state(4)==='Not reached'?'1':'2','Selected demo run')}${metric(model?'Input tokens':'Tool errors',model?'1,080':scenario==='failure'?'1':'0','Illustrative fixture')}${metric(model?'Output tokens':'Retries',model?'160':'0','Illustrative fixture')}</div><section class="panel"><div class="panel-head"><h2>${model?'Model operations':'Tool inventory'}</h2><small>Selected run</small></div><div class="table-scroll"><table><thead><tr><th>${model?'MODEL':'TOOL'}</th><th>ROLE</th><th>STATUS</th><th></th></tr></thead><tbody>${(model?[['Demo model','Structured action proposal',1]]:[['getBillingRecord','Read billing record',0],['issueSyntheticRefund','Mutate synthetic ledger',4]]).map(([name,role,i])=>`<tr><td><strong>${name}</strong></td><td>${role}</td><td>${pill(state(i))}</td><td><button class="link" data-node="${i}">Inspect call →</button></td></tr>`).join('')}</tbody></table></div></section>`}
function bind(){document.querySelectorAll('[data-page]').forEach(e=>e.onclick=()=>go(e.dataset.page));document.querySelectorAll('[data-node]').forEach(e=>e.onclick=()=>{selected=Number(e.dataset.node);page='workflow';render()});document.querySelectorAll('[data-mode]').forEach(e=>e.onclick=()=>{mode=e.dataset.mode;render()});document.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>{tab=e.dataset.tab;render()});document.querySelectorAll('[data-scenario]').forEach(e=>e.onclick=()=>{scenario=e.dataset.scenario;mode='execution';selected=scenario==='failure'?4:3;go('workflow')});document.querySelectorAll('[role="button"]').forEach(e=>e.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();e.click()}});const set=(id,fn)=>{const e=document.getElementById(id);if(e)e.onclick=fn};const s=document.getElementById('scenario');if(s)s.onchange=()=>{scenario=s.value;mode='execution';selected=scenario==='failure'?4:3;render()};set('approve',()=>{approved=true;rejected=false;scenario='approval';render();toast('Demo approval recorded. Synthetic action marked complete.')});set('reject',()=>{rejected=true;approved=false;scenario='approval';render();toast('Demo action rejected. No synthetic effect recorded.')});set('replay',()=>{if(scenario==='approval'){approved=false;rejected=false}mode='execution';selected=3;render();toast('Demo scenario reset. No live agent was executed.')});set('suite',()=>{suiteRun=true;render();toast('Showing illustrative suite results.')});set('policy-open',()=>{policyOpen=!policyOpen;render()});set('export',()=>{const data={source:'R2M frontend demonstration',synthetic:true,run:scenarios[scenario].id,steps:steps.map((name,i)=>({name,status:state(i)})),policy:'REFUND-001 v1.2',signed:false};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`r2m-${scenarios[scenario].id}-demo.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo evidence exported.')})}
render();

